<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { LanguageSwitcherContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: LanguageSwitcherContract  = $props();
const open=control(()=>p.open,untrack(()=>p.defaultOpen),false,open=>p.onOpenChange?.({open}));const uid=$props.id();let root:HTMLElement;onMount(()=>{const outside=(e:PointerEvent)=>{if(!root.contains(e.target as Node))open.request(false);};document.addEventListener('pointerdown',outside);return()=>document.removeEventListener('pointerdown',outside);});let trigger=$state<HTMLButtonElement>();function key(e:KeyboardEvent){if(!ignoredKey(e)&&e.key==='Escape'&&open.value){e.preventDefault();open.request(false);void tick().then(()=>{if(!open.value)trigger?.focus();});}}
</script>
<nav aria-label="언어 선택" bind:this={root} {...owned('language-switcher','root',open.value?'open':'closed')} onkeydown={key}>{#if p.options.length>=3}<button bind:this={trigger} type="button" aria-expanded={open.value} aria-controls={uid} {...owned('language-switcher','trigger',open.value?'open':'closed')} onclick={()=>open.request(!open.value)}>언어: {p.options.find(x=>x.locale===p.currentLocale)?.nativeLabel}</button>{/if}<ul style:position={p.options.length<3?'static':undefined} id={uid} hidden={p.options.length>=3&&!open.value} {...owned('language-switcher','list',p.options.length<3||open.value?'open':'closed')}>{#each p.options as option(option.locale)}<li><a href={option.href} target={option.separateService?'_blank':undefined} rel={option.separateService?'noopener noreferrer':undefined} aria-label={option.nativeLabel} aria-describedby={option.separateService?`${uid}-${option.locale}-window`:undefined} lang={option.locale} hreflang={option.locale} aria-current={p.currentLocale===option.locale?'true':undefined} {...owned('language-switcher','option',p.currentLocale===option.locale&&'current')} onclick={()=>{if(option.locale!==p.currentLocale)p.onLocaleRequest?.({locale:option.locale,href:option.href});}}>{option.nativeLabel}<span aria-hidden="true"> ({option.translatedLabel})</span>{#if option.separateService}<span id={`${uid}-${option.locale}-window`}> (새 창)</span>{/if}</a></li>{/each}</ul></nav>
